WITH joined AS (SELECT e.*, s.store_name, s.opened_date FROM inventory e LEFT JOIN stores s ON e.store_id = s.id) SELECT DATE_TRUNC('YEAR', last_restock) AS year_start, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, PERCENTILE_APPROX(quantity, 0.95) AS quantity_p95, APPROX_PERCENTILE(quantity, 0.5) AS quantity_p50 FROM joined GROUP BY DATE_TRUNC('YEAR', last_restock) ORDER BY quantity_p95 DESC NULLS LAST;
